import {estimateCost} from './api-usage.js';
const $=s=>document.querySelector(s);
const pricing=await fetch('/data/pricing.json').then(r=>r.json());
$('#roles').innerHTML=['player','judge'].map(role=>`<section data-role="${role}"><h2>${role==='player'?'游玩模型':'评审模型'}</h2><label>接入方式<select name="mode"><option value="api">API 密钥 · 按量计费</option><option value="subscription">本地 Codex 订阅 · 官方登录</option></select></label><label>供应商<select name="provider"><option value="openai">OpenAI / Codex</option><option value="deepseek">DeepSeek</option><option value="custom">兼容接口</option></select></label><label>模型名称<input name="model" placeholder="填写你的账号可用模型" required></label><div class="api-fields"><label>完整 Chat Completions 接口地址<input name="url" type="url" value="https://api.openai.com/v1/chat/completions"></label><label>API 密钥<input name="key" type="password" autocomplete="new-password" placeholder="已保存时留空保留，永不回显"></label></div><p class="subscription-note hint" hidden>授权留在本机。请在终端执行 codex login 完成官方登录，再点击下方检查授权。不需要复制订阅 token。此模式仍受账号额度约束，不能直接搬到托管服务器供访客共用。</p><p class="hint">可选自定义单价；留空时仅 OpenAI 官方接口的已知精确模型采用价格快照，其他模型显示未计价。</p><div class="rates">${[['input','输入'],['cached','缓存输入'],['output','输出']].map(([n,t])=>`<label>${t}单价<input name="rate-${n}" type="number" min="0" step="any" placeholder="可选"></label>`).join('')}</div></section>`).join('');
function update(section){const sub=section.querySelector('[name=mode]').value==='subscription';section.querySelector('.api-fields').hidden=sub;section.querySelector('.subscription-note').hidden=!sub;section.querySelector('[name=provider]').disabled=sub;}
for(const section of document.querySelectorAll('[data-role]')){
 section.querySelector('[name=mode]').onchange=()=>update(section);
 section.querySelector('[name=provider]').onchange=e=>{const value=e.target.value;section.querySelector('[name=url]').value=value==='deepseek'?'https://api.deepseek.com/chat/completions':value==='openai'?'https://api.openai.com/v1/chat/completions':'';};
}
let local=false;
try{const r=await fetch('/api/model-settings');if(r.ok&&r.headers.get('content-type')?.includes('application/json')){const d=await r.json();local=true;for(const [role,v]of Object.entries(d.settings)){const section=document.querySelector(`[data-role=${role}]`);for(const k of ['mode','provider','model','url'])if(v[k])section.querySelector(`[name=${k}]`).value=v[k];for(const k of ['input','cached','output'])if(v.rates?.[k]!=null)section.querySelector(`[name=rate-${k}]`).value=v.rates[k];update(section);}}}catch{}
$('#remote-note').hidden=local;for(const el of $('#settings-form').querySelectorAll('input,select,button'))el.disabled=!local;
if(local)for(const section of document.querySelectorAll('[data-role]'))update(section);
$('#message').textContent=local?'本地执行器已连接。配置只保存在本机 .auth/，不写入网页存储或导出报告。':'当前未连接本地执行器；请使用上方入口。';
async function request(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'操作失败');return d;}
$('#settings-form').onsubmit=async e=>{e.preventDefault();try{const data={};for(const section of document.querySelectorAll('[data-role]')){const get=n=>section.querySelector(`[name="${n}"]`).value;const values=['input','cached','output'].map(k=>get('rate-'+k));if(values.some(Boolean)&&!values.every(Boolean))throw Error('自定义单价需同时填写输入、缓存、输出三项');data[section.dataset.role]={mode:get('mode'),provider:get('provider'),model:get('model'),url:get('url'),key:get('key'),rates:values.every(Boolean)?Object.fromEntries(['input','cached','output'].map((k,i)=>[k,Number(values[i])])):null};}await request('/api/model-settings',data);for(const k of document.querySelectorAll('[name=key]'))k.value='';$('#message').textContent='已保存；玩家与评审的后续调用将使用此配置。';}catch(e){$('#message').textContent=e.message;}};
$('#check-codex').onclick=async()=>{try{const d=await fetch('/api/codex-status').then(r=>r.json());$('#message').textContent=d.message;}catch{$('#message').textContent='无法连接本机授权检查';}};
$('#test-model').onclick=async()=>{const b=$('#test-model');b.disabled=true;$('#message').textContent='正在发送一次测试…';try{const d=await request('/api/model-test',{role:'player'});$('#message').textContent=`连接成功。本次测试已知 ${d.summary.total} Token；用量缺失 ${d.summary.missing} 次。测试单独计入，不归入剧本评测。`;}catch(e){$('#message').textContent=e.message;}finally{b.disabled=false;}};
$('#estimate-model').innerHTML=Object.keys(pricing.models).map(m=>`<option>${m}</option>`).join('');
function estimate(){const input=Number($('#estimate-input').value),cached=Number($('#estimate-cached').value),output=Number($('#estimate-output').value);if(![input,cached,output].every(n=>Number.isSafeInteger(n)&&n>=0)||cached>input){$('#estimate').textContent='请填写非负整数，缓存不能超过输入';return;}const cost=estimateCost({input,cached,output,cacheWrite:0},pricing.models[$('#estimate-model').value]);$('#estimate').textContent=`本次假设用量的参考费用：USD $${cost.toFixed(4)}`;}
for(const id of ['estimate-model','estimate-input','estimate-cached','estimate-output'])$('#'+id).oninput=estimate;
$('#price-source').textContent=`价格核对：${pricing.checkedAt}。${pricing.assumption}`;const a=document.createElement('a');a.href=pricing.source;a.textContent=' 查看官方价格';a.target='_blank';a.rel='noopener';$('#price-source').append(a);estimate();
